func newClassicMobileAppsDeleteCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagYes    bool
		flagDryRun bool
		flagName   string
		fromFile   string
	)

	cmd := &cobra.Command{
		Use:   "delete [<id>]",
		Short: "Delete a mobile_device_application",
		Example: `  # Delete a mobile_device_application (with confirmation)
  jamf-cli pro classic-mobile-apps delete 1

  # Delete by name
  jamf-cli pro classic-mobile-apps delete --name "Example" --yes

  # Delete without confirmation prompt
  jamf-cli pro classic-mobile-apps delete 1 --yes`,
		Annotations: map[string]string{"jamf:destructive": "true", "jamf:api": "pro-classic", "jamf:gateway-privileges": "applications:delete"},
		Args:        cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			// --from-file: bulk delete from a file of IDs or names
			if fromFile != "" {
				entries, err := readDeleteFile(fromFile)
				if err != nil {
					return fmt.Errorf("reading --from-file: %w", err)
				}
				if len(entries) == 0 {
					return fmt.Errorf("--from-file %q: no entries found", fromFile)
				}
				type bulkEntry struct{ id, label string }
				bulk := make([]bulkEntry, 0, len(entries))
				noInputBulk, _ := cmd.Flags().GetBool("no-input")
				for _, entry := range entries {
					if isNumericID(entry) {
						if entry == "0" {
							return fmt.Errorf("--from-file: ID 0 is not valid (Jamf Pro uses 0 as a sentinel value)")
						}
						bulk = append(bulk, bulkEntry{id: entry, label: entry})
					} else {
						var resolvedID string
						if resolvedID == "" {
							id, err := resolveClassicNameToIDForApply(reqCtx, ctx.Client, "mobiledeviceapplications", "mobiledeviceapplications", entry, "update", noInputBulk)
							if err != nil {
								return fmt.Errorf("resolving %q: %w", entry, err)
							}
							resolvedID = id
						}
						if resolvedID == "" {
							return fmt.Errorf("no mobile_device_application found matching %q", entry)
						}
						bulk = append(bulk, bulkEntry{id: resolvedID, label: entry})
					}
				}
				// Deduplicate resolved IDs to avoid double-delete errors.
				{
					seen := make(map[string]bool, len(bulk))
					deduped := bulk[:0]
					for _, e := range bulk {
						if !seen[e.id] {
							seen[e.id] = true
							deduped = append(deduped, e)
						}
					}
					bulk = deduped
				}
				if flagDryRun {
					for _, e := range bulk {
						fmt.Fprintf(os.Stderr, "[dry-run] Would delete mobile_device_application %q (id: %s)\n", e.label, e.id)
					}
					return nil
				}
				if !flagYes {
					if noInputBulk {
						return fmt.Errorf("destructive operation requires --yes when --no-input is set")
					}
					fmt.Fprintf(os.Stderr, "⚠️  This will delete %d mobiledeviceapplications. Type 'yes' to confirm: ", len(bulk))
					var confirm string
					fmt.Scanln(&confirm)
					if confirm != "yes" {
						return fmt.Errorf("aborted")
					}
				}
				if err := cooldown.Enforce(ctx.ProfileName, noInputBulk, ctx.DestructiveCooldown); err != nil {
					return err
				}
				var okCount, failCount int
				var firstErr error
				for _, e := range bulk {
					delPath := fmt.Sprintf("/JSSResource/mobiledeviceapplications/id/%s", url.PathEscape(e.id))
					resp, err := ctx.Client.Do(reqCtx, "DELETE", delPath, nil)
					if err != nil {
						fmt.Fprintf(os.Stderr, "delete mobile_device_application %q (id: %s) failed: %v\n", e.label, e.id, err)
						if firstErr == nil {
							firstErr = err
						}
						failCount++
						continue
					}
					resp.Body.Close()
					if resp.StatusCode == http.StatusNoContent || resp.StatusCode == http.StatusOK {
						fmt.Fprintf(os.Stderr, "Deleted mobile_device_application %q (id: %s)\n", e.label, e.id)
						okCount++
					} else {
						fmt.Fprintf(os.Stderr, "delete mobile_device_application %q (id: %s) failed: HTTP %d\n", e.label, e.id, resp.StatusCode)
						if firstErr == nil {
							firstErr = fmt.Errorf("HTTP %d", resp.StatusCode)
						}
						failCount++
					}
				}
				cooldown.Record(ctx.ProfileName)
				return batchDeleteError(cmd, okCount, failCount, firstErr, "mobiledeviceapplications deletes")
			}

			// Resolve ID from --name or positional arg
			var resolvedID string
			noInput, _ := cmd.Flags().GetBool("no-input")
			if flagName != "" {
				id, err := resolveClassicNameToIDForApply(reqCtx, ctx.Client, "mobiledeviceapplications", "mobiledeviceapplications", flagName, "update", noInput)
				if err != nil {
					return err
				}
				if id == "" {
					return fmt.Errorf("no mobile_device_application found with name %q", flagName)
				}
				resolvedID = id
			} else if len(args) > 0 {
				resolvedID = args[0]
			} else {
				return fmt.Errorf("provide an <id> argument or --name")
			}

			if flagDryRun {
				fmt.Fprintf(os.Stderr, "[dry-run] Would delete mobile_device_application %s\n", resolvedID)
				return nil
			}
			if !flagYes {
				if noInput {
					return fmt.Errorf("destructive operation requires --yes when --no-input is set")
				}
				fmt.Fprintf(os.Stderr, "This will delete mobile_device_application %s. Type 'yes' to confirm: ", resolvedID)
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			if err := cooldown.Enforce(ctx.ProfileName, noInput, ctx.DestructiveCooldown); err != nil {
				return err
			}
			path := fmt.Sprintf("/JSSResource/mobiledeviceapplications/id/%s", url.PathEscape(resolvedID))

			resp, err := ctx.Client.Do(reqCtx, "DELETE", path, nil)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			if resp.StatusCode == http.StatusNoContent || resp.StatusCode == http.StatusOK {
				cooldown.Record(ctx.ProfileName)
				fmt.Fprintln(os.Stderr, "Deleted successfully")
				return nil
			}

			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")
	cmd.Flags().StringVar(&flagName, "name", "", "Look up mobile_device_application by name")
	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to file listing IDs or names to delete (one per line, # comments ignored)")
	cmd.MarkFlagsMutuallyExclusive("from-file", "name")

	return cmd
}

func newClassicMobileAppsApplyCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		fromFile          string
		flagYes           bool
		flagDryRun        bool
		flagScaffold      bool
		flagSet           []string
		flagName          string
		flagAppconfigFile string
	)

	cmd := &cobra.Command{
		Use:         "apply",
		Short:       "Create or replace a mobile_device_application by name",
		Annotations: map[string]string{"jamf:api": "pro-classic", "jamf:gateway-privileges": "applications:create,applications:read,applications:update"},
		Long: `Create or replace a mobile_device_application. Reads XML from --from-file, --set or stdin.

The name field in the input XML is used to check if the resource already
exists. If it does, the resource is replaced (with confirmation).
If not, a new resource is created.

Body fields are derived from the Classic API spec (schema "mobile_device_application").
Run with --scaffold to print a complete XML template.
The template populates every optional section with one specimen entry,
including references whose <id> points at nothing on your instance — delete
the sections you do not need. A dangling reference is answered with a 500.
Optional sections: app_configuration, general, scope, self_service, vpp

Allowed values:
  general.deployment_type: Make Available in Self Service | Install Automatically/Prompt Users to Install

The Classic API does not reject an out-of-range value — it substitutes
its default silently — so --set refuses one rather than letting it through.`,
		Example: `  # Apply a mobile_device_application from an XML file
  jamf-cli pro classic-mobile-apps apply --from-file mobile_device_application.xml

  # Apply from stdin
  cat mobile_device_application.xml | jamf-cli pro classic-mobile-apps apply

  # Apply without replacement confirmation
  jamf-cli pro classic-mobile-apps apply --from-file mobile_device_application.xml --yes`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if flagScaffold {
				return printClassicScaffold(bodySpecClassicMobileApps)
			}
			reqCtx := cmd.Context()

			// Read input
			data, err := readApplyInput(fromFile)

			anyFileFlag := flagAppconfigFile != ""
			if err != nil && !anyFileFlag {
				return err
			}
			err = nil

			// Inject file fields before name extraction so name-fallback (if any)
			// can populate <general><name> for lookup.
			data, err = injectClassicFileFields(data, "mobile_device_application", []classicFileFieldSpec{
				{FilePath: flagAppconfigFile, ParentPath: []string{"app_configuration"}, LeafName: "preferences", Encoding: "xml-cdata", NameFallback: "none"},
			})
			if err != nil {
				return err
			}

			// Extract name: for fetch-merge-put resources, --name is the primary
			// input (body typically empty); fall back to XML name if flag absent.
			var name string

			if flagName != "" {
				name = flagName
			} else {
				name, err = extractClassicName(data, "mobile_device_application")
				if err != nil {
					return fmt.Errorf("--name is required when input body is empty: %w", err)
				}
			}

			// Check if resource exists by name (read-only, runs even in dry-run)
			noInput, _ := cmd.Flags().GetBool("no-input")
			id, err := resolveClassicNameToIDForApply(reqCtx, ctx.Client, "mobiledeviceapplications", "mobiledeviceapplications", name, "update", noInput)
			if err != nil {
				return err
			}

			if id == "" {
				// Not found — create (not allowed for fetch-merge-put resources)

				return fmt.Errorf("no mobile_device_application found with name %q — this resource must already exist (apply is fetch-merge-put only)", name)

			}

			// Found — replace
			if flagDryRun {
				fmt.Fprintf(os.Stderr, "[dry-run] Would replace mobile_device_application %q (id: %s)\n", name, id)
				return nil
			}
			if !flagYes {
				if noInput {
					return fmt.Errorf("mobile_device_application %q already exists (id: %s); use --yes to replace when --no-input is set", name, id)
				}
				fmt.Fprintf(os.Stderr, "mobile_device_application %q already exists (id: %s) and will be replaced. Type 'yes' to confirm: ", name, id)
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			// Fetch the existing full record and overlay the file field(s) — the
			// user's input (if any) is ignored beyond name resolution; AppConfig
			// injection preserves every other field on the record.
			_, fullBody, ferr := fetchClassicFullXMLByName(reqCtx, ctx.Client, "mobiledeviceapplications", name)
			if ferr != nil || len(fullBody) == 0 {
				return fmt.Errorf("fetching existing mobile_device_application for merge-put: %w", ferr)
			}
			data = fullBody
			data, err = injectClassicFileFields(data, "mobile_device_application", []classicFileFieldSpec{
				{FilePath: flagAppconfigFile, ParentPath: []string{"app_configuration"}, LeafName: "preferences", Encoding: "xml-cdata", NameFallback: "none"},
			})
			if err != nil {
				return err
			}

			updatePath := fmt.Sprintf("/JSSResource/mobiledeviceapplications/id/%s", url.PathEscape(id))
			resp, err := ctx.Client.Do(reqCtx, "PUT", updatePath, bytes.NewReader(data))
			if err != nil {
				return err
			}

			defer resp.Body.Close()
			fmt.Fprintf(os.Stderr, "Replaced mobile_device_application %q (id: %s)\n", name, id)
			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to XML input file (or pipe XML to stdin)")
	cmd.Flags().BoolVar(&flagScaffold, "scaffold", false, "Print an XML body template for this resource and exit")
	cmd.Flags().StringArrayVar(&flagSet, "set", nil, "Set a body field in dot notation (key=value, repeatable). Builds the whole body, so it cannot be combined with --from-file")
	_ = cmd.RegisterFlagCompletionFunc("set", func(_ *cobra.Command, _ []string, _ string) ([]string, cobra.ShellCompDirective) {
		return []string{"app_configuration.preferences=", "general.allow_user_to_delete=", "general.bundle_id=", "general.category.id=", "general.category.name=", "general.deploy_as_managed_app=", "general.deploy_automatically=", "general.deployment_type=", "general.description=", "general.display_name=", "general.external_url=", "general.free=", "general.host_externally=", "general.icon.data=", "general.icon.id=", "general.icon.name=", "general.icon.uri=", "general.id=", "general.internal_app=", "general.ipa.data=", "general.ipa.name=", "general.ipa.uri=", "general.itunes_country_region=", "general.itunes_store_url=", "general.itunes_sync_time=", "general.keep_app_updated_on_devices=", "general.keep_description_and_icon_up_to_date=", "general.make_available_after_install=", "general.mobile_device_provisioning_profile=", "general.name=", "general.os_type=", "general.prevent_backup_of_app_data=", "general.remove_app_when_mdm_profile_is_removed=", "general.require_network_tethered=", "general.site.id=", "general.site.name=", "general.take_over_management=", "general.version=", "scope.all_jss_users=", "scope.all_mobile_devices=", "self_service.feature_on_main_page=", "self_service.notification=", "self_service.notification_message=", "self_service.notification_subject=", "self_service.self_service_after_install_button_text=", "self_service.self_service_description=", "self_service.self_service_icon.data=", "self_service.self_service_icon.filename=", "self_service.self_service_icon.id=", "self_service.self_service_icon.name=", "self_service.self_service_icon.uri=", "self_service.self_service_install_button_text=", "vpp.assign_vpp_device_based_licenses=", "vpp.vpp_admin_account_id="}, cobra.ShellCompDirectiveNoSpace
	})

	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt when replacing")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")
	cmd.Flags().StringVar(&flagName, "name", "", "Name of the existing mobile_device_application to update (required when body is empty)")

	cmd.Flags().StringVar(&flagAppconfigFile, "appconfig-file", "", "Path to an AppConfig plist; contents populate <app_configuration><preferences>")

	return cmd
}
